// Repro for data_byte failure: uart_frame_tx must send data LSB first.
// Expected to FAIL on uart_frame_tx_buggy.v (it sends MSB first).
`timescale 1ns / 1ps
module tb_uart_frame_tx;
    localparam integer CLKS = 4;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
    wire       tx;
    wire       busy;
    integer    errors = 0;
    reg [10:0] frame;

    uart_frame_tx #(.CLKS_PER_BIT(CLKS)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    initial begin
        #200000;
        $display("ERROR: timeout");
        $fatal(1, "TEST FAILED: timeout");
    end

    task wait_negedges(input integer n);
        integer i;
        begin
            for (i = 0; i < n; i = i + 1) @(negedge clk);
        end
    endtask

    // Send one byte and capture the 11 frame bits at mid-bit.
    // frame[0]=start, frame[1..8]=data bit 0..7 on the line, frame[9]=parity, frame[10]=stop
    task send_and_capture(input [7:0] d);
        integer k;
        integer guard;
        begin
            @(negedge clk);
            data  = d;
            start = 1'b1;
            @(negedge clk);
            start = 1'b0;
            guard = 0;
            while (tx !== 1'b0 && guard < 4 * CLKS) begin
                @(negedge clk);
                guard = guard + 1;
            end
            if (tx !== 1'b0) begin
                $display("ERROR: start bit never appeared for data 0x%02h", d);
                errors = errors + 1;
            end
            wait_negedges(CLKS / 2);
            frame[0] = tx;
            for (k = 1; k <= 10; k = k + 1) begin
                wait_negedges(CLKS);
                frame[k] = tx;
            end
            guard = 0;
            while (busy === 1'b1 && guard < 20 * CLKS) begin
                @(negedge clk);
                guard = guard + 1;
            end
            wait_negedges(2 * CLKS);
        end
    endtask

    task check_byte(input [7:0] d);
        integer k;
        begin
            send_and_capture(d);
            if (frame[0] !== 1'b0) begin
                $display("ERROR: data 0x%02h start bit = %b, expected 0", d, frame[0]);
                errors = errors + 1;
            end
            for (k = 0; k < 8; k = k + 1) begin
                if (frame[k + 1] !== d[k]) begin
                    $display("ERROR: data 0x%02h line bit %0d = %b, expected d[%0d] = %b (LSB first)",
                             d, k, frame[k + 1], k, d[k]);
                    errors = errors + 1;
                end
            end
        end
    endtask

    initial begin
        rst = 1'b1;
        wait_negedges(4);
        rst = 1'b0;
        wait_negedges(4);

        check_byte(8'h01);
        check_byte(8'hA3);
        check_byte(8'h80);
        check_byte(8'h3C);

        if (errors != 0) begin
            $display("ERROR: data_byte test found %0d mismatches", errors);
            $fatal(1, "TEST FAILED: data_byte");
        end
        $display("TEST PASSED: data_byte");
        $finish;
    end
endmodule
