        report_and_finish(1'b0);
    end

    task wait_negedges(input integer n);
        integer i;
        begin
            for (i = 0; i < n; i = i + 1) @(negedge clk);
        end
    endtask

    initial begin
        rst = 1'b1;
        wait_negedges(4);
        rst = 1'b0;
        wait_negedges(4);

        // Check 1: one frame keeps busy high for exactly 11 bit times.
        @(negedge clk);
        data  = 8'h55;
        start = 1'b1;
        @(negedge clk);
        start = 1'b0;
        busy_cycles = 0;
        while (busy === 1'b1 && busy_cycles < 100 * CLKS) begin
            busy_cycles = busy_cycles + 1;
            @(negedge clk);
        end
        if (busy_cycles != FRAME_CYCLES) begin
            $display("ERROR: single frame busy for %0d cycles, expected %0d (11 bits x %0d)",
                     busy_cycles, FRAME_CYCLES, CLKS);
            errors = errors + 1;
        end

        wait_negedges(3 * CLKS);

        // Check 2: with start held high, frames must not start closer than 11 bit times.
        @(negedge clk);
        data        = 8'h55;
        start       = 1'b1;
        prev_busy   = busy;
        cyc         = 0;
        first_rise  = -1;
        second_rise = -1;
        while (second_rise < 0 && cyc < 200 * CLKS) begin
            @(negedge clk);
            cyc = cyc + 1;
            if (busy === 1'b1 && prev_busy !== 1'b1) begin
                if (first_rise < 0)
                    first_rise = cyc;
                else
                    second_rise = cyc;
            end
            prev_busy = busy;
        end
        start = 1'b0;
        if (first_rise < 0 || second_rise < 0) begin
            $display("ERROR: back-to-back frames not observed (first_rise=%0d second_rise=%0d)",
                     first_rise, second_rise);
            errors = errors + 1;
        end else if ((second_rise - first_rise) < FRAME_CYCLES) begin
            $display("ERROR: back-to-back frame period %0d cycles, expected at least %0d (stop bit too short)",
                     second_rise - first_rise, FRAME_CYCLES);
            errors = errors + 1;
        end

        if (errors != 0) begin
            $display("ERROR: frame_period test found %0d mismatches", errors);
            report_and_finish(1'b0);
        end else
            report_and_finish(1'b1);
    end
endmodule
